package main

import (
	"errors"
	"fmt"
)

type Order struct {
	Name     string
	Quantity int
}

var ErrMissing = errors.New("missing item")
var ErrStock = errors.New("insufficient stock")

func reserve(stock map[string]int, order Order) error {
	if order.Quantity <= 0 {
		return fmt.Errorf("invalid quantity")
	}
	count, ok := stock[order.Name]
	if !ok {
		return fmt.Errorf("%s: %w", order.Name, ErrMissing)
	}
	if count < order.Quantity {
		return fmt.Errorf("%s: %w", order.Name, ErrStock)
	}
	stock[order.Name] = count - order.Quantity
	return nil
}
func main() {
	stock := map[string]int{"pen": 3}
	orders := []Order{{"pen", 2}, {"pen", 2}, {"bag", 1}, {"pen", 0}}
	for _, order := range orders {
		err := reserve(stock, order)
		switch {
		case err == nil:
			fmt.Println("ok")
		case errors.Is(err, ErrStock):
			fmt.Println("stock")
		case errors.Is(err, ErrMissing):
			fmt.Println("missing")
		default:
			fmt.Println("invalid")
		}
	}
	fmt.Println(stock["pen"])
}

// Output:
// ok
// stock
// missing
// invalid
// 1

