type Order struct {
	Title    string `json:"title"`
	Quantity int    `json:"quantity"`
}

func decode(text string) (Order, error) {
	var order Order
	if err := json.Unmarshal([]byte(text), &order); err != nil {
		return Order{}, err
	}
	order.Title = strings.TrimSpace(order.Title)
	if order.Title == "" || order.Quantity <= 0 {
		return Order{}, errors.New("invalid order")
	}
	return order, nil
}
func main() {
	inputs := []string{`{"title":"Book","quantity":2}`, `{"title":`, `{"title":"Book","quantity":-1}`, `{"quantity":2}`}
	for _, input := range inputs {
		order, err := decode(input)
		if err != nil {
			fmt.Println("invalid")
			continue
		}
		fmt.Println(order.Title, order.Quantity)
	}
}

