package main

import "strings"

type Todo struct {
	ID    int    `json:"id"`
	Title string `json:"title"`
	Done  bool   `json:"done"`
}
type List struct {
	Items  []Todo `json:"items"`
	NextID int    `json:"nextId"`
}

func (l *List) Add(title string) (int, bool) {
	title = strings.TrimSpace(title)
	if title == "" {
		return 0, false
	}
	l.NextID++
	l.Items = append(l.Items, Todo{ID: l.NextID, Title: title})
	return l.NextID, true
}
func (l *List) Complete(id int) bool {
	for i := range l.Items {
		if l.Items[i].ID == id {
			l.Items[i].Done = true
			return true
		}
	}
	return false
}
func (l List) Report() (int, int) {
	done, pending := 0, 0
	for _, item := range l.Items {
		if item.Done {
			done++
		} else {
			pending++
		}
	}
	return done, pending
}
