package main

import (
	"encoding/json"
	"reflect"
	"testing"
)

func TestEmpty(t *testing.T) {
	var list List
	done, pending := list.Report()
	if done != 0 || pending != 0 || list.Complete(1) {
		t.Fatal("empty list changed")
	}
}
func TestAdd(t *testing.T) {
	var list List
	id, ok := list.Add(" Learn Go ")
	if id != 1 || !ok || list.Items[0].Title != "Learn Go" || list.Items[0].Done {
		t.Fatal("invalid first task")
	}
	id, ok = list.Add(" ")
	if id != 0 || ok || list.NextID != 1 || len(list.Items) != 1 {
		t.Fatal("rejected title changed state")
	}
	id, ok = list.Add("Write test")
	if id != 2 || !ok {
		t.Fatal("ID was consumed")
	}
}
func TestComplete(t *testing.T) {
	var list List
	list.Add("A")
	list.Add("B")
	if !list.Complete(1) || !list.Complete(1) || list.Complete(99) {
		t.Fatal("completion contract")
	}
	done, pending := list.Report()
	if done != 1 || pending != 1 || !list.Items[0].Done || list.Items[1].Done {
		t.Fatal("wrong completion state")
	}
}
func TestJSON(t *testing.T) {
	var original List
	original.Add("Learn Go")
	original.Add("Write test")
	original.Complete(1)
	data, err := json.Marshal(original)
	if err != nil {
		t.Fatal(err)
	}
	var restored List
	if err = json.Unmarshal(data, &restored); err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(original, restored) {
		t.Fatal("state changed during JSON round trip")
	}
	id, ok := restored.Add("Ship")
	if id != 3 || !ok {
		t.Fatal("restored ID counter")
	}
}
