package main

import (
	"encoding/json"
	"fmt"
	"os"
)

func run() error {
	var list List
	fmt.Println(list.Add("Learn Go"))
	fmt.Println(list.Add(" "))
	fmt.Println(list.Add("Write test"))
	fmt.Println(list.Complete(1))
	fmt.Println(list.Complete(1))
	fmt.Println(list.Complete(99))
	done, pending := list.Report()
	fmt.Printf("done: %d pending: %d\n", done, pending)
	data, err := json.Marshal(list)
	if err != nil {
		return err
	}
	var restored List
	if err = json.Unmarshal(data, &restored); err != nil {
		return err
	}
	done, pending = restored.Report()
	fmt.Printf("restored: %d %d %d\n", len(restored.Items), done, pending)
	fmt.Println(restored.Add("Ship"))
	var empty List
	done, pending = empty.Report()
	fmt.Println("empty:", done, pending)
	return nil
}
func main() {
	if err := run(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

